/**
 * Command.Panel: the search row, the listbox and the status inside the palette, mounted with the panel so each opening starts from an empty query.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/command.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/combobox'
import { normalizeProps } from '@zag-js/solid'

import {
  Each,
  Icon,
  claimSlot,
  createCell,
  createDerived,
  mergeParts,
  scope,
  useDirection,
  useMachine,
  watchEffect,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/overlays/command.module.css'
import Kbd from '../structure/Kbd'
import Skeleton from '../structure/Skeleton'
import type { CommandItem } from './Command'

export interface CommandPanelProps {
  items: CommandItem[]
  placeholder: string
  escapeHint: string
  filter: 'contains' | false
  loading: boolean
  emptyMessage: string
  onQueryChange?: (query: string) => void
  onCommand?: () => void
}

/** Command.Panel: the search row, the listbox and the status inside the palette, mounted with the panel so each opening starts from an empty query. */
export default function CommandPanel(given: CommandPanelProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const uid = createUniqueId()
    const query = createCell('')
    const collator = createDerived(
      () => new Intl.Collator(undefined, { usage: 'search', sensitivity: 'base' }),
    )
    const needle = createDerived(() => query.value.normalize('NFC'))
    const matches = createDerived(
      () => (item: CommandItem) =>
        ((text: string) =>
          needle.value === '' ||
          Array.from({ length: Math.max(0, text.length - needle.value.length + 1) }, (_, at) =>
            text.slice(at, at + needle.value.length),
          ).some((part) => collator.value.compare(part, needle.value) === 0))(
          (item.keywords === undefined
            ? item.label
            : `${item.label} ${item.keywords.join(' ')}`
          ).normalize('NFC'),
        ),
    )
    const shown = createDerived(() =>
      props.filter === false ? props.items : props.items.filter((item) => matches.value(item)),
    )
    const runs = createDerived(() =>
      shown.value.reduce(
        (into, item) => (
          item.group !== undefined && into.at(-1)?.[0]?.group === item.group
            ? into.at(-1)?.push(item)
            : into.push([item]),
          into
        ),
        [] as CommandItem[][],
      ),
    )
    const firstEnabled = createDerived(() => shown.value.find((item) => item.disabled !== true)?.id)
    const showEmpty = createDerived(() => !props.loading && shown.value.length === 0)
    const announcement = createDerived(() =>
      props.loading
        ? 'Loading commands…'
        : shown.value.length === 0
          ? props.emptyMessage
          : `${shown.value.length} commands`,
    )
    const documentDirection = useDirection()
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          collection: zag.collection({
            items: shown.value,
            itemToValue: (item) => item.id,
            itemToString: (item) => item.label,
            isItemDisabled: (item) => item.disabled === true,
          }),
          open: true,
          disableLayer: true,
          value: [],
          closeOnSelect: false,
          selectionBehavior: 'preserve' as const,
          allowCustomValue: true,
          inputBehavior: 'autohighlight' as const,
          placeholder: props.placeholder,
          onInputValueChange: (details) => {
            void ((query.value = details.inputValue), props.onQueryChange?.(details.inputValue))
          },
          onSelect: (details) => {
            void (props.items.find((item) => item.id === details.itemValue)?.onSelect(),
            props.onCommand?.())
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    const effect1 = () => {
      props.onQueryChange?.(query.value)
    }
    onMount(effect1)
    const effect2 = () => {
      void (
        api.value.highlightedValue === null &&
        firstEnabled.value !== undefined &&
        api.value.setHighlightValue(firstEnabled.value)
      )
    }
    watchEffect(
      createMemo(() => api.value.highlightedValue ?? firstEnabled.value),
      effect2,
      true,
    )
    return (
      <>
        {/* search */}
        <div class={styles.search}>
          <Icon name="search" size="md" />
          {/* input */}
          <input
            {...mergeParts(api.value.getInputProps(), {
              class: styles.input,
              'aria-label': props.placeholder,
              onkeydown: ($event: KeyboardEvent) =>
                $event.key === 'Escape' && api.value.setInputValue(''),
            })}
          />
          <Kbd>{props.escapeHint}</Kbd>
        </div>
        {/* body */}
        <div class={styles.body} data-dialog-part="body">
          {/* list */}
          <ul
            {...mergeParts(api.value.getContentProps(), {
              class: styles.listbox,
              hidden: undefined,
              'aria-labelledby': undefined,
              'aria-label': 'Suggestions',
            })}
          >
            <Each of={runs.value} by={(run) => run.map((item) => item.id).join(' ')} renew>
              {(run, at) => (
                <>
                  {run[0]?.group === undefined ? (
                    <Each of={run} by={(item) => `${query.value}/${item.id}`} renew>
                      {(item) => (
                        <li
                          {...mergeParts(
                            api.value.getItemProps({ item: item, persistFocus: true }),
                            { class: styles.item, 'aria-labelledby': `${uid}-label-${item.id}` },
                          )}
                        >
                          {item.icon !== undefined ? (
                            <span class={styles.glyph}>
                              <Icon name={item.icon} size="sm" />
                            </span>
                          ) : null}
                          <span class={styles.label} id={`${uid}-label-${item.id}`}>
                            {item.label}
                          </span>
                          {item.hint !== undefined ? (
                            <span class={styles.hint}>
                              <Kbd>{item.hint}</Kbd>
                            </span>
                          ) : null}
                        </li>
                      )}
                    </Each>
                  ) : (
                    <li class={styles.section} role="presentation">
                      <span
                        {...mergeParts(api.value.getItemGroupLabelProps({ htmlFor: `${at()}` }), {
                          class: styles.groupLabel,
                        })}
                      >
                        {run[0]?.group}
                      </span>
                      <ul
                        {...mergeParts(api.value.getItemGroupProps({ id: `${at()}` }), {
                          class: styles.group,
                        })}
                      >
                        <Each of={run} by={(item) => `${query.value}/${item.id}`} renew>
                          {(item) => (
                            <li
                              {...mergeParts(
                                api.value.getItemProps({ item: item, persistFocus: true }),
                                {
                                  class: styles.item,
                                  'aria-labelledby': `${uid}-label-${item.id}`,
                                },
                              )}
                            >
                              {item.icon !== undefined ? (
                                <span class={styles.glyph}>
                                  <Icon name={item.icon} size="sm" />
                                </span>
                              ) : null}
                              <span class={styles.label} id={`${uid}-label-${item.id}`}>
                                {item.label}
                              </span>
                              {item.hint !== undefined ? (
                                <span class={styles.hint}>
                                  <Kbd>{item.hint}</Kbd>
                                </span>
                              ) : null}
                            </li>
                          )}
                        </Each>
                      </ul>
                    </li>
                  )}
                </>
              )}
            </Each>
          </ul>
          {props.loading ? (
            <div class={styles.rows} aria-hidden="true">
              <Each of={[0, 1, 2]} by={(skeleton) => skeleton}>
                {() => (
                  <div class={styles.row}>
                    <Skeleton textStep="sm" />
                  </div>
                )}
              </Each>
            </div>
          ) : null}
          {showEmpty.value ? (
            <div class={styles.empty} aria-hidden="true">
              {props.emptyMessage}
            </div>
          ) : null}
        </div>
        <div class={styles.status} role="status" aria-live="polite">
          {announcement.value}
        </div>
      </>
    )
  })
}
